import{_ as e,c as a,o as r,a5 as n,bE as l,bF as s,bG as o,bH as i,bI as d}from"./chunks/framework.BmNIwhaK.js";const _=JSON.parse('{"title":"シナリオ実行およびスケジューラー設定","description":"クロスブラウジング、マルチ解像度、バックグラウンド並列実行オプション、および定期テスト自動化のためのスケジューラー構成ガイドです。","frontmatter":{"title":"シナリオ実行およびスケジューラー設定","description":"クロスブラウジング、マルチ解像度、バックグラウンド並列実行オプション、および定期テスト自動化のためのスケジューラー構成ガイドです。","head":[["meta",{"name":"keywords","content":"SyncETA, シナリオ実行, クロスブラウジング, Playwright 実行, ヘッドレスモード, 並列実行, テストスケジューラー"}],["meta",{"property":"og:title","content":"シナリオ実行およびスケジューラー設定 | Empasy Docs"}],["meta",{"property":"og:description","content":"クロスブラウジング、マルチ解像度、バックグラウンド並列実行オプション、および定期テスト自動化のためのスケジューラー構成ガイドです。"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/synceta/scenario-run"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/synceta/scenario-run"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/synceta/scenario-run"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/synceta/scenario-run"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/synceta/scenario-run"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/synceta/scenario-run"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"シナリオ実行およびスケジューラー設定 | Empasy Docs"}],["meta",{"name":"twitter:description","content":"クロスブラウジング、マルチ解像度、バックグラウンド並列実行オプション、および定期テスト自動化のためのスケジューラー構成ガイドです。"}]],"sort":400},"headers":[],"relativePath":"ja/synceta/scenario-run.md","filePath":"ja/synceta/scenario-run.md","lastUpdated":1795293539000}'),c={name:"ja/synceta/scenario-run.md"};function g(h,t,p,m,y,f){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="シナリオ実行およびスケジューラー設定" tabindex="-1">シナリオ実行およびスケジューラー設定 <a class="header-anchor" href="#シナリオ実行およびスケジューラー設定" aria-label="Permalink to “シナリオ実行およびスケジューラー設定”">​</a></h1><p>SyncETA は、単一シナリオの即時実行から大規模なクロスブラウジング検証、時間帯別の自動回帰テストのためのスケジューラー機能までをサポートしています。</p><hr><h2 id="_1-シナリオの直接実行-direct-execution" tabindex="-1">1. シナリオの直接実行（Direct Execution） <a class="header-anchor" href="#_1-シナリオの直接実行-direct-execution" aria-label="Permalink to “1. シナリオの直接実行（Direct Execution）”">​</a></h2><p>シナリオ詳細画面右上の <strong>「実行」</strong> ボタンをクリックすることで、テストを即座に起動できます。</p><p><img src="'+l+'" alt="シナリオ実行オプション設定" loading="lazy"></p><h3 id="主な実行オプション仕様" tabindex="-1">主な実行オプション仕様 <a class="header-anchor" href="#主な実行オプション仕様" aria-label="Permalink to “主な実行オプション仕様”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">設定項目</th><th style="text-align:left;">説明</th><th style="text-align:left;">デフォルト値</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>データセット（Data Set）</strong></td><td style="text-align:left;">テスト実行時に適用するデータセットを選択（変数置換）</td><td style="text-align:left;">未適用</td></tr><tr><td style="text-align:left;"><strong>実行ブラウザ</strong></td><td style="text-align:left;">Chromium、Chrome、Microsoft Edge、Firefox、WebKit から選択</td><td style="text-align:left;">Chrome</td></tr><tr><td style="text-align:left;"><strong>ビューポートサイズ</strong></td><td style="text-align:left;">ブラウザの幅・高さの解像度を指定（レスポンシブテスト）</td><td style="text-align:left;">1920x1080</td></tr><tr><td style="text-align:left;"><strong>反復実行方式</strong></td><td style="text-align:left;"><strong>直列</strong>: N 回順次反復実行<br><strong>並列</strong>: N 個のブラウザインスタンスを同時起動して並列実行</td><td style="text-align:left;">直列 1 回</td></tr><tr><td style="text-align:left;"><strong>ヘッドレスモード（Headless）</strong></td><td style="text-align:left;">ブラウザ GUI ウィンドウを表示せず、バックグラウンドプロセスとして高速実行</td><td style="text-align:left;">無効</td></tr><tr><td style="text-align:left;"><strong>実行後のブラウザ終了</strong></td><td style="text-align:left;">テスト完了後にブラウザコンテキストを自動クリーンアップするかどうか</td><td style="text-align:left;">有効</td></tr><tr><td style="text-align:left;"><strong>動画保存（Save Video）</strong></td><td style="text-align:left;">テスト実行の全過程を MP4 ビデオファイルとしてキャプチャ・保存</td><td style="text-align:left;">有効</td></tr><tr><td style="text-align:left;"><strong>ステップ間遅延時間（Step Delay）</strong></td><td style="text-align:left;">各レコード実行間のデフォルト待機時間（ms）を設定</td><td style="text-align:left;">0ms</td></tr></tbody></table><hr><h2 id="_2-スケジューラーによる定期自動実行" tabindex="-1">2. スケジューラーによる定期自動実行 <a class="header-anchor" href="#_2-スケジューラーによる定期自動実行" aria-label="Permalink to “2. スケジューラーによる定期自動実行”">​</a></h2><p>定期的な回帰検証（夜間ビルドテスト、定期デプロイ後のスモークテストなど）のために、Cron ベースのスケジューラーを設定できます。</p><h3 id="ステップ-1-スケジューラーメニューへの移動" tabindex="-1">ステップ 1: スケジューラーメニューへの移動 <a class="header-anchor" href="#ステップ-1-スケジューラーメニューへの移動" aria-label="Permalink to “ステップ 1: スケジューラーメニューへの移動”">​</a></h3><p>左側サイドバーから <strong>「スケジューラー」</strong> メニューへ移動します。</p><p><img src="'+s+'" alt="スケジューラーメニュー移動" loading="lazy"></p><h3 id="ステップ-2-実行周期および時間帯の指定" tabindex="-1">ステップ 2: 実行周期および時間帯の指定 <a class="header-anchor" href="#ステップ-2-実行周期および時間帯の指定" aria-label="Permalink to “ステップ 2: 実行周期および時間帯の指定”">​</a></h3><p>毎日の特定時刻、毎週の特定曜日、または指定された分単位の間隔で実行周期を設定します。</p><p><img src="'+o+'" alt="実行周期設定" loading="lazy"></p><h3 id="ステップ-3-対象シナリオおよび実行パラメーターのマッピング" tabindex="-1">ステップ 3: 対象シナリオおよび実行パラメーターのマッピング <a class="header-anchor" href="#ステップ-3-対象シナリオおよび実行パラメーターのマッピング" aria-label="Permalink to “ステップ 3: 対象シナリオおよび実行パラメーターのマッピング”">​</a></h3><p>スケジュールに従って実行するシナリオ一覧とブラウザタイプ、解像度環境を指定します。</p><p><img src="'+i+'" alt="シナリオおよび環境設定" loading="lazy"></p><h3 id="ステップ-4-スケジュール登録内容および実行履歴の確認" tabindex="-1">ステップ 4: スケジュール登録内容および実行履歴の確認 <a class="header-anchor" href="#ステップ-4-スケジュール登録内容および実行履歴の確認" aria-label="Permalink to “ステップ 4: スケジュール登録内容および実行履歴の確認”">​</a></h3><p>登録されたスケジューラー一覧で、次回実行予定時刻および直近の実行成否をモニタリングします。</p><p><img src="'+d+'" alt="スケジューラー登録確認" loading="lazy"></p>',23)])])}const b=e(c,[["render",g]]);export{_ as __pageData,b as default};
